module.exports = "<ion-header class=\"interior-header\" dir=\"rtl\">\n  \n  <app-page-header titleKey=\"pageHeader.tuner-plus/alphabet/alphabet\" fallback=\"/TunerPlus\">\n\n  </app-page-header>\n</ion-header>\n\n<ion-content dir=\"rtl\" class=\"alphabet-content\">\n  <div class=\"container\">\n    <div class=\"hero-banner\">\n      <span class=\"hero-chip\">🔤 ابزار تعاملی فارسی کلاس اول</span>\n      <h1>کارگاه الفبا و نشانه‌های فارسی</h1>\n      <p>شناخت ۳۲ نشانه زبان فارسی، شکل‌های اول، وسط و آخر، همراه با مثال‌های کتاب فارسی پایه اول و مسابقه تندخوانی.</p>\n    </div>\n\n    <!-- فیلترها و جستجو -->\n    <div class=\"search-filter-card\">\n      <div class=\"search-box\">\n        <ion-icon name=\"search-outline\"></ion-icon>\n        <input type=\"text\" [(ngModel)]=\"searchQuery\" placeholder=\"جستجوی نشانه یا کلمه (مثلاً ب، آب، باران)...\" />\n        <button *ngIf=\"searchQuery\" (click)=\"searchQuery = ''\" class=\"clear-btn\">✕</button>\n      </div>\n      <div class=\"filter-chips\">\n        <button [class.active]=\"selectedFilter === 'all'\" (click)=\"selectedFilter = 'all'\">همه نشانه‌ها</button>\n        <button [class.active]=\"selectedFilter === 'vowel'\" (click)=\"selectedFilter = 'vowel'\">مصوت‌ها / صداها</button>\n        <button [class.active]=\"selectedFilter === 'consonant'\" (click)=\"selectedFilter = 'consonant'\">صامت‌ها / حروف</button>\n      </div>\n    </div>\n\n    <div class=\"alphabet-workspace\">\n      <!-- ستون سمت چپ: شبکه تمام نشانه‌ها -->\n      <div class=\"letters-grid-container\">\n        <h3>انتخاب نشانه:</h3>\n        <div class=\"letters-grid\">\n          <button \n            *ngFor=\"let item of filteredLetters\" \n            class=\"letter-card\" \n            [class.selected]=\"selectedLetter.letter === item.letter\"\n            (click)=\"selectLetter(item)\">\n            <span class=\"big-letter\">{{ item.letter }}</span>\n            <span class=\"letter-name\">{{ item.name }}</span>\n          </button>\n        </div>\n      </div>\n\n      <!-- ستون سمت راست: کارت جزئیات نشانه انتخاب شده -->\n      <div class=\"details-panel\" *ngIf=\"selectedLetter\">\n        <div class=\"detail-card\">\n          <div class=\"detail-header\">\n            <div class=\"detail-badge\">{{ selectedLetter.category === 'vowel' ? 'نشانه صدا' : 'نشانه صامت' }}</div>\n            <button class=\"sound-btn\" (click)=\"playAudioSynthesis(selectedLetter.name + ' مثل ' + selectedLetter.example)\">\n              <ion-icon name=\"volume-high-outline\"></ion-icon>\n              <span>تلفظ صوتی</span>\n            </button>\n          </div>\n\n          <div class=\"hero-letter-display\">\n            <span class=\"display-glyph\">{{ selectedLetter.letter }}</span>\n            <h2>نام نشانه: {{ selectedLetter.name }}</h2>\n          </div>\n\n          <div class=\"forms-section\">\n            <h4>شکل‌های مختلف در کلمه:</h4>\n            <div class=\"forms-chips\">\n              <span *ngFor=\"let form of selectedLetter.forms\" class=\"form-chip\">{{ form }}</span>\n            </div>\n          </div>\n\n          <div class=\"examples-section\">\n            <h4>کلمات نمونه کتاب اول ابتدایی:</h4>\n            <div class=\"example-box\">\n              <span class=\"example-word\">✏️ {{ selectedLetter.example }}</span>\n              <small class=\"example-meaning\">({{ selectedLetter.exampleMeaning }})</small>\n            </div>\n          </div>\n        </div>\n\n        <!-- بازی سریع تشخیص نشانه -->\n        <div class=\"quiz-card\">\n          <div class=\"quiz-head\">\n            <h4>🎯 بازی سنجش نشانه</h4>\n            <span class=\"quiz-score\">امتیاز: {{ quizScore }}</span>\n          </div>\n          <p class=\"quiz-prompt\">این چه نشانه‌ای است؟</p>\n          <div class=\"quiz-target-letter\">{{ letters[quizCurrentIndex].letter }}</div>\n\n          <div class=\"quiz-options\">\n            <button \n              *ngFor=\"let opt of quizOptions\"\n              class=\"quiz-opt-btn\"\n              [class.correct]=\"quizAnswered && opt === letters[quizCurrentIndex].name\"\n              [class.wrong]=\"quizAnswered && quizSelectedOption === opt && opt !== letters[quizCurrentIndex].name\"\n              (click)=\"answerQuiz(opt)\">\n              {{ opt }}\n            </button>\n          </div>\n\n          <div *ngIf=\"quizAnswered\" class=\"quiz-feedback\">\n            <span *ngIf=\"quizIsCorrect\" class=\"success-msg\">🎉 آفرین! پاسخ کاملاً درست است.</span>\n            <span *ngIf=\"!quizIsCorrect\" class=\"error-msg\">❌ نشانه درست {{ letters[quizCurrentIndex].name }} بود.</span>\n            <button class=\"next-btn\" (click)=\"generateQuizQuestion()\">سوال بعدی ❯</button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <app-footer></app-footer>\n</ion-content>\n";

